#include <stdint.h>
#include <string.h>
#include <stdlib.h>

typedef struct {
    uint32_t magic;
    uint32_t abi_version;
    uint32_t header_size;
    uint32_t reserved;
    int32_t initialized;
} BpInterface;

static BpInterface g_interface = {
    0x49554849u, /* little-endian bytes: I H U I */
    1u,
    (uint32_t)sizeof(BpInterface),
    0u,
    0,
};

__declspec(dllexport) void *BP_GetInterface(const char *name, uint32_t abi) {
    if (name == NULL || strcmp(name, "ihui.bp") != 0) return NULL;
    if (abi != 1u) return NULL;
    return (void *)&g_interface;
}

__declspec(dllexport) int BP_Initialize(void *raw) {
    if (raw == NULL) return -1;
    BpInterface *iface = (BpInterface *)raw;
    if (iface->magic != 0x49554849u || iface->abi_version != 1u) return -2;
    iface->initialized = 1;
    return 0;
}

__declspec(dllexport) void BP_Shutdown(void *raw) {
    if (raw == NULL) return;
    ((BpInterface *)raw)->initialized = 0;
}

/* Optional side-channel for manual verification: exports an integer state. */
__declspec(dllexport) int BP_GetFixtureState(void) {
    return g_interface.initialized;
}
